package io.github.jesterportfolio.hearth.survival.rpg;

import java.util.*;import java.security.MessageDigest;
import org.bukkit.*;import org.bukkit.entity.Player;import org.bukkit.event.*;import org.bukkit.event.entity.*;import org.bukkit.event.player.*;import org.bukkit.inventory.ItemStack;
import net.kyori.adventure.text.Component;
import io.github.jesterportfolio.hearth.survival.VanillaPlayerFiles;
import io.github.jesterportfolio.hearth.survival.skills.WorldAccessPolicy.Role;

/** keepInventory 경로의 실제 소지품을 1회 분할하고 native 저장 후에만 드랍 목록을 공개한다. */
public final class RpgDeath implements Listener,AutoCloseable {
    public java.util.function.Consumer<PlayerDeathEvent> beforeSplit=e->{};private final RpgRuntime r;public final DeathJournal journal;private final Map<UUID,PlayerDeathEvent> pending=new HashMap<>();
    public RpgDeath(RpgRuntime r,UUID group)throws Exception{this.r=r;journal=new DeathJournal(r.plugin.getDataFolder().toPath().toAbsolutePath(),group);Bukkit.getPluginManager().registerEvents(this,r.plugin);}
    private static ItemStack[] copy(ItemStack[] input){return Arrays.stream(input).map(i->i==null?null:i.clone()).toArray(ItemStack[]::new);}
    public static String hash(ItemStack[] items){try{var digest=MessageDigest.getInstance("SHA-256");for(var item:items){byte[] b=item==null||item.isEmpty()?new byte[0]:item.serializeAsBytes();digest.update(java.nio.ByteBuffer.allocate(4).putInt(b.length).array());digest.update(b);}return HexFormat.of().formatHex(digest.digest());}catch(Exception e){throw new IllegalStateException(e);}}
    @EventHandler(priority=EventPriority.LOWEST,ignoreCancelled=true) public void damage(EntityDamageEvent e){if(e.getEntity() instanceof Player p){Role role=r.role(p.getWorld());if(role==null||!r.policy.ready(role)||journal.held(p.getUniqueId())||!r.aura.loaded(p.getUniqueId()))e.setCancelled(true);}}
    @EventHandler(priority=EventPriority.LOWEST,ignoreCancelled=true) public void death(PlayerDeathEvent e){var p=e.getEntity();Role role=r.role(p.getWorld());if(pending.get(p.getUniqueId())==e)return;
        if(r.runtime.economy().transactions.busy(p.getUniqueId())){e.setCancelled(true);r.hold(new IllegalStateException("DEATH_DURING_NATIVE_TRANSACTION"));return;}if(!r.ready()||!r.policy.ready(role)||journal.held(p.getUniqueId())||pending.containsKey(p.getUniqueId())||!r.aura.loaded(p.getUniqueId())||!e.getItemsToKeep().isEmpty()){e.setCancelled(true);p.sendMessage(Component.text("사망 처리 준비가 끝나지 않아 처리를 보류했습니다."));return;}
        int oldLevel=p.getLevel(),oldTotal=p.getTotalExperience();float oldExp=p.getExp();var changedAura=new HashMap<dev.aurelium.auraskills.api.skill.Skill,Double>();var nativeBefore=copy(p.getInventory().getContents());var top=p.getOpenInventory().getTopInventory();int[] inputs=DeathInventory.inputs(top.getType());var workspace=new ItemStack[1+inputs.length];workspace[0]=p.getItemOnCursor().clone();for(int i=0;i<inputs.length;i++){var item=top.getItem(inputs[i]);workspace[i+1]=item==null?null:item.clone();}var before=Arrays.copyOf(nativeBefore,nativeBefore.length+workspace.length);System.arraycopy(workspace,0,before,nativeBefore.length,workspace.length);var retained=copy(before);var slots=new ArrayList<RpgPolicy.Slot>();var extras=new ArrayList<ItemStack>();e.getDrops().forEach(item->extras.add(item.clone()));
        try{beforeSplit.accept(e);var policy=r.policy.deaths().get(role);for(int i=0;i<before.length;i++){var item=before[i];if(item==null||item.isEmpty())continue;int left=item.getAmount();for(var drop:extras)if(i<nativeBefore.length&&!e.getKeepInventory()&&left>0&&drop.isSimilar(item)){int amount=Math.min(left,drop.getAmount());left-=amount;drop.setAmount(drop.getAmount()-amount);}slots.add(new RpgPolicy.Slot(i,hash(new ItemStack[]{item}),item.getAmount(),r.aura.itemRate(item,policy.dropRate()),r.isCharm(item)));}
            boolean charmNeeded=r.policy.needsCharm(slots,policy);var split=r.policy.split(slots,charmNeeded,java.util.concurrent.ThreadLocalRandom.current());var drops=new ArrayList<ItemStack>();for(var s:slots){int kept=split.kept().getOrDefault(s.index(),0);if(kept==0)retained[s.index()]=null;else retained[s.index()].setAmount(kept);int lost=split.dropped().getOrDefault(s.index(),0);if(lost>0){var item=before[s.index()].clone();item.setAmount(lost);drops.add(item);}}
            final ItemStack[] after=DeathInventory.pack(retained,nativeBefore.length);boolean protectedVanilla=split.charmSlot()!=null&&r.policy.charmScopes().contains(RpgPolicy.CharmScope.VANILLA_XP),protectedAura=split.charmSlot()!=null&&r.policy.charmScopes().contains(RpgPolicy.CharmScope.AURA_XP);
            var user=r.aura.api.getUser(p.getUniqueId());var auraBefore=changedAura;if(policy.loss()==RpgPolicy.XpLoss.THIRD&&r.policy.auraLoss()&&!protectedAura)for(var skill:r.aura.api.getGlobalRegistry().getSkills())if(skill.isEnabled())auraBefore.put(skill,user.getSkillXp(skill));
            long points=VanillaXp.at(p.getLevel())+Math.round(p.getExp()*VanillaXp.next(p.getLevel()));long vanillaAfter=points;if(policy.loss()==RpgPolicy.XpLoss.THIRD&&r.policy.vanillaLoss()&&!protectedVanilla){if(r.policy.xpScope()==RpgPolicy.XpScope.VANILLA_PROGRESS||r.policy.xpScope()==RpgPolicy.XpScope.BOTH_PROGRESS)vanillaAfter=VanillaXp.at(p.getLevel())+r.policy.remainingThird(points-VanillaXp.at(p.getLevel()));else vanillaAfter=r.policy.remainingThird(points);}
            var ticket=journal.acquire(p.getUniqueId(),hash(before),hash(after),before);pending.put(p.getUniqueId(),e);
            p.setItemOnCursor(null);for(int input:inputs)top.setItem(input,null);p.getInventory().setContents(after);if(policy.loss()!=RpgPolicy.XpLoss.VANILLA||protectedVanilla){var xp=VanillaXp.decode(vanillaAfter);p.setLevel(xp.level());p.setExp(xp.fraction());p.setTotalExperience(Math.toIntExact(vanillaAfter));e.setKeepLevel(true);e.setDroppedExp(policy.loss()==RpgPolicy.XpLoss.THIRD&&r.policy.lostXpOrbs()&&!protectedVanilla?Math.toIntExact(points-vanillaAfter):0);}
            for(var entry:auraBefore.entrySet()){double amount=entry.getValue();if(!Double.isFinite(amount)||amount<0)throw new IllegalStateException("DEATH_AURA_XP_DATA");double loss=switch(r.policy.rounding()){case FLOOR->Math.floor(amount/3);case CEIL->Math.ceil(amount/3);case NEAREST->Math.floor(amount/3+.5);default->throw new IllegalStateException("XP_ROUNDING_UNSET");};user.setSkillXp(entry.getKey(),Math.max(0,amount-loss));}
            VanillaPlayerFiles.save(Bukkit.getServer().getLevelDirectory(),p.getUniqueId(),p::saveData);
            e.setKeepInventory(true);e.getDrops().clear();extras.stream().filter(item->!item.isEmpty()).forEach(e.getDrops()::add);e.getDrops().addAll(drops);
            Bukkit.getScheduler().runTask(r.plugin,()->{try{if(!hash(p.getInventory().getContents()).equals(hash(after)))throw new IllegalStateException("DEATH_INVENTORY_CHANGED");VanillaPlayerFiles.save(Bukkit.getServer().getLevelDirectory(),p.getUniqueId(),p::saveData);ticket.clean();}catch(Exception failure){r.hold(failure);}});
        }catch(Exception failure){e.setCancelled(true);try{if(!journal.held(p.getUniqueId()))journal.acquire(p.getUniqueId(),hash(before),hash(before),before);p.getInventory().setContents(nativeBefore);p.setItemOnCursor(workspace[0]);for(int i=0;i<inputs.length;i++)top.setItem(inputs[i],workspace[i+1]);p.setLevel(oldLevel);p.setExp(oldExp);p.setTotalExperience(oldTotal);var user=r.aura.api.getUser(p.getUniqueId());changedAura.forEach(user::setSkillXp);VanillaPlayerFiles.save(Bukkit.getServer().getLevelDirectory(),p.getUniqueId(),p::saveData);}catch(Exception rollback){failure.addSuppressed(rollback);}r.hold(failure);p.sendMessage(Component.text("사망 결과 확인 필요 · 원본을 자동 재지급하지 않습니다."));}
    }
    @EventHandler public void respawn(PlayerRespawnEvent e){pending.remove(e.getPlayer().getUniqueId());}
    @EventHandler public void quit(PlayerQuitEvent e){pending.remove(e.getPlayer().getUniqueId());}
    public void close(){HandlerList.unregisterAll(this);pending.clear();}
}
